 78→func TestDetectPresence_WithKiroDir(t *testing.T) {
 79→	t.Parallel()
 80→
 81→	tempDir := t.TempDir()
 82→	if err := os.MkdirAll(filepath.Join(tempDir, ".kiro"), 0o750); err != nil {
 83→		t.Fatalf("failed to create .kiro dir: %v", err)
 84→	}
 85→
 86→	// DetectPresence uses paths.WorktreeRoot which won't resolve in a temp dir,
