421→func assertKiroHookCommand(t *testing.T, entries []kiroHookEntry, expectedCommand string) {
422→	t.Helper()
423→	if len(entries) == 0 {
424→		t.Errorf("expected hook entry with command %q, got empty slice", expectedCommand)
425→		return
426→	}
427→	found := false
428→	for _, entry := range entries {
429→		if entry.Command == expectedCommand {
430→			found = true
431→			break
432→		}
433→	}
434→	if !found {
435→		commands := make([]string, 0, len(entries))
436→		for _, entry := range entries {
437→			commands = append(commands, entry.Command)
438→		}
439→		t.Errorf("expected hook command %q, got %v", expectedCommand, commands)
440→	}
441→}
